const input = $input.first()?.json ?? {};
const query = String(input.query ?? input.query_text ?? '').trim();
if (!query) throw new Error('query is required');
const list = (value) => Array.isArray(value) ? [...new Set(value.map((item) => String(item ?? '').trim()).filter(Boolean))] : [];
const candidateLimit = Math.max(1, Math.min(200, Number.isInteger(input.candidate_limit) ? input.candidate_limit : 40));
const resultLimit = Math.max(1, Math.min(candidateLimit, Number.isInteger(input.result_limit) ? input.result_limit : 8));
return [{ json: {
  query,
  texts: [query],
  tenant_id: String(input.tenant_id ?? 'default').trim() || 'default',
  access_groups: list(input.access_groups),
  decision_steps: list(input.decision_steps),
  project_types: list(input.project_types),
  geography: list(input.geography),
  metadata_filter: input.metadata_filter && typeof input.metadata_filter === 'object' && !Array.isArray(input.metadata_filter) ? input.metadata_filter : {},
  candidate_limit: candidateLimit,
  result_limit: resultLimit,
  context_radius: Math.max(0, Math.min(3, Number.isInteger(input.context_radius) ? input.context_radius : 1)),
} }];

const state = $('Normalize Recall Request').first().json;
const result = $input.first()?.json ?? {};
const embedding = Array.isArray(result.embeddings?.[0]) ? result.embeddings[0] : null;
if (!embedding || embedding.length !== 768) throw new Error('query embedding must contain 768 values');
return [{ json: {
  ...state,
  embedding_literal: `[${embedding.join(',')}]`,
  embedding_model: String(result.model ?? ''),
  embedding_dimensions: Number(result.dimensions ?? 0),
} }];

const state = $('Normalize Recall Request').first().json;
const candidates = $input.all().map((item) => item.json).filter((row) => row.chunk_id);
return [{ json: { ...state, candidates } }];

const state = $input.first().json;
return [{ json: {
  ...state,
  candidates: [],
  chunk_ids: [],
  rerank: {
    method: 'skipped-no-candidates',
    provider: null,
    model: null,
    response_id: null,
    candidate_count: 0,
  },
} }];

