SELECT * FROM expand_kb_context(
  ARRAY(SELECT jsonb_array_elements_text($1::jsonb))::uuid[],
  $2::integer
) ORDER BY hit_rank, ordinal;

parameters.jsCode:
const state = $('Prepare Context Expansion').first().json;
const contexts = $input.all().map((item) => item.json).filter((row) => row.chunk_id).sort((a, b) => Number(a.hit_rank) - Number(b.hit_rank) || Number(a.ordinal) - Number(b.ordinal));
const seen = new Set();
const citations = contexts.filter((row) => {
  if (seen.has(row.chunk_id)) return false;
  seen.add(row.chunk_id);
  return true;
}).map((row) => ({
  citation_id: row.chunk_key,
  chunk_id: row.chunk_id,
  document_id: row.document_id,
  title: row.title,
  source_type: row.source_type,
  source_url: row.source_url,
  object_key: row.object_key,
  page_start: row.page_start,
  page_end: row.page_end,
  section: row.section,
  ordinal: row.ordinal,
  is_direct_hit: Boolean(row.is_direct_hit),
}));
return [{ json: {
  query: state.query,
  tenant_id: state.tenant_id,
  candidates: state.candidates,
  contexts,
  citations,
  retrieval: {
    filter_stage: 'tenant + access_groups + metadata + decision_steps + project_types + geography',
    fusion: 'keyword FTS/trigram + pgvector cosine RRF',
    rerank: state.rerank,
    context_radius: state.context_radius,
    source_read: 'kb_chunks content with page/source locators',
  },
} }];
